script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    // If field value is present in form, we read from form else from data broker
    var articleType = api.data?.record?.form?.fields?.article_type?.value ||
        api.data?.fetch_article_type?.result?.article_type?.value;


    // Hide Blocks tab if article type is wiki
    if (articleType === 'wiki' || articleType === 'markdown')  {
        return true;
    }
    return !((api.context.props.table === "kb_knowledge" || api.context.props.table.startsWith("kb_template") || api.context.props.table.startsWith("u_kb_template")) && api.data.plugin_status_1.output.active);
}

css.value:
* {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    margin: 0px;
    font-size: var(--now-global-font-size--sm, 12px);
    color: rgb(var(--now-color--secondary-1, 79, 82, 189));
    padding-left: 5px;
    padding-right: 5px;
}

script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.state.isGenAiGenerating || api.state.isSearchLoading) {
    return helpers.translateSync('Drafting article...');
  }
	return helpers.translateSync('Use AI to draft this article?');
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.genAiSourceRecordId == null || api.state.genAiSourceRecordId == '';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.genAiSourceRecordId != null && api.state.genAiSourceRecordId != '';
}
